/*
 * A PostgreSQL extension for executing queries in an embedded chDB library.
 */

#include "postgres.h"

#include "funcapi.h"
#include "miscadmin.h"
#include "nodes/makefuncs.h"
#include "utils/builtins.h"
#include "utils/guc.h"

#include <limits.h>

#include "gucs.h"
#include "helper.h"
#include "module.h"
#include "native.h"
#include "srf.h"
#include "version.h" /* Generated by Makefile. */

CHDB_MODULE_MAGIC("chdb");

/*
 * GUCs for settings to be passed to chDB, referenced by CHDB_GUCS().
 */
static int chdb_max_memory  = 0;
static int chdb_max_threads = 0;
static int chdb_max_parsers = 0;

/*
 * _PG_init is the entry-point for the library.
 */
void
_PG_init(void);
void
_PG_init(void) {
    if (IsBinaryUpgrade) {
        return;
    }

    CHDB_GUCS("chdb");
}

/*
 * Function returns the full chdb extension library version.
 */
PG_FUNCTION_INFO_V1(pgchdb_version);
Datum
pgchdb_version(PG_FUNCTION_ARGS) {
    PG_RETURN_TEXT_P(cstring_to_text(PGCHCB_VERSION));
}

/*
 * Execute a query against a temporary chDB database and return its rows,
 * mapping chDB values to the Postgres types named in the caller's column
 * definition list.
 */
PG_FUNCTION_INFO_V1(chdb_query);
Datum
chdb_query(PG_FUNCTION_ARGS) {
    char* sql         = text_to_cstring(PG_GETARG_TEXT_P(0));
    TupleDesc tupdesc = chdb_srf_tupdesc(fcinfo, "chdb", "chdb_query");

    /* Hand off to the helper. */
    chdbHelperContext ctx = {
        .cmd         = CHDB_CMD_SELECT,
        .max_memory  = (uint16_t)chdb_max_memory,
        .max_threads = (uint16_t)chdb_max_threads,
        .max_parsers = (uint16_t)chdb_max_parsers,
    };
    chdbHelper* helper = chdb_helper_start(&ctx, sql, NULL, NULL, 0);
    return chdb_select_receive(
        sql, (ReturnSetInfo*)fcinfo->resultinfo, tupdesc, helper
    );
}
